mapper.insert:
INSERT INTO diagram_cell_provenance
    (diagram_id, cell_id, canvas_version, provenance_ref, semantic_hash, support_type, current_citation_id)
SELECT previous.diagram_id, previous.cell_id, #{canvasVersion}, previous.provenance_ref,
       previous.semantic_hash, previous.support_type, previous.current_citation_id
FROM diagram_cell_provenance previous
WHERE previous.diagram_id = #{plan.diagramId}
  AND previous.canvas_version = #{previousVersion}
  AND previous.cell_id IN

      #{cellId}

mapper.update:
UPDATE grounded_run_control
SET state = 'COMPLETED', completed_at = UTC_TIMESTAMP(3), updated_at = UTC_TIMESTAMP(3)
WHERE run_id = #{plan.runId} AND owner_key = #{plan.ownerKey}
  AND request_id = #{plan.requestId} AND state = 'RUNNING'
  AND generation = #{plan.expectedRunGeneration}
